interface.definition:
a!localVariables(
  local!nominationdetails: #"_a-0000e6bc-0703-8000-9bf8-011c48011c48_3461738"(
    nominationId: ri!nomination.nominationId
  ).data,
  local!reviewersComment: index(local!nominationdetails,"vettingReviewersComment",{}),
  local!isNewVersion: if(
    a!isNullOrEmpty(ri!nomination.createdOn),
    true,
    if(
      todatetime(ri!nomination.createdOn) > #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12333392",
      true,
      false
    )
  ),
  #"SYSTEM_SYSRULES_sectionLayout_v1"(
    label: "Additional Vetting",
    labelColor: "SECONDARY",
    showWhen: ri!showWhen,
    contents: {
      #"SYSTEM_SYSRULES_richTextDisplayField"(
        labelPosition: "COLLAPSED",
        value: #"SYSTEM_SYSRULES_richTextItem_v1"(
          text: { "To be completed by DPP Operations" },
          size: "SMALL",
          style: "EMPHASIS"
        )
      ),
      #"SYSTEM_SYSRULES_cardLayout"(
        contents: {
          #"SYSTEM_SYSRULES_richTextDisplayField"(
            value: {
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: "Based on HR/Inspections findings, does the Operations team believe additional vetting is required?   ",
                style: "STRONG"
              ),
              #"SYSTEM_SYSRULES_richTextIcon"(
                icon: if(
                  and(
                    ri!nomination.isOpsAdditionalVettingReqCompleted = true,
                    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(
                      ri!nomination.isOpsAdditionalVettingReq
                    )
                  ),
                  "check-circle",
                  if(
                    and(
                      ri!nomination.isOpsAdditionalVettingReq = true,
                      #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(
                        ri!nomination.isOpsAdditionalVettingReqCompleted
                      )
                    ),
                    "clock-o",
                    if(
                      and(
                        #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(
                          ri!nomination.isOpsAdditionalVettingReq
                        ),
                        #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(
                          ri!nomination.isOpsAdditionalVettingReqCompleted
                        )
                      ),
                      "minus-circle",
                      null
                    )
                  )
                ),
                color: if(
                  and(
                    ri!nomination.isOpsAdditionalVettingReqCompleted = true,
                    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(
                      ri!nomination.isOpsAdditionalVettingReq
                    )
                  ),
                  "POSITIVE",
                  if(
                    and(
                      ri!nomination.isOpsAdditionalVettingReq = true,
                      #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(
                        ri!nomination.isOpsAdditionalVettingReqCompleted
                      )
                    ),
                    "ACCENT",
                    if(
                      and(
                        #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(
                          ri!nomination.isOpsAdditionalVettingReq
                        ),
                        #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(
                          ri!nomination.isOpsAdditionalVettingReqCompleted
                        )
                      ),
                      "NEGATIVE",
                      null
                    )
                  )
                ),
                size: "MEDIUM",
                caption: if(
                  and(
                    ri!nomination.isOpsAdditionalVettingReqCompleted = true,
                    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(
                      ri!nomination.isOpsAdditionalVettingReq
                    )
                  ),
                  "Completed",
                  if(
                    and(
                      ri!nomination.isOpsAdditionalVettingReq = true,
                      #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(
                        ri!nomination.isOpsAdditionalVettingReqCompleted
                      )
                    ),
                    "In Progress",
                    if(
                      and(
                        #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(
                          ri!nomination.isOpsAdditionalVettingReq
                        ),
                        #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(
                          ri!nomination.isOpsAdditionalVettingReqCompleted
                        )
                      ),
                      "Not Requested",
                      null
                    )
                  )
                )
              ),
              char(10),
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                  value: ri!nomination.isOpsAdditionalVettingReq,
                  isBoolean: true
                )
              )
            }
          ),
          #"SYSTEM_SYSRULES_paragraphField"(
            label: if(
              toboolean(local!isNewVersion) = true,
              "DPP Ops Additional Vetting Comments",
              "Additional Vetting Comments"
            ),
            readOnly: or(ri!isEditReadonly, ri!readOnly),
            value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
              value: ri!nomination.vettingComments,
              isBoolean: false
            )
          ),
          #"SYSTEM_SYSRULES_paragraphField"(
            label: "Additional Vetting reviewer's Comments",
            labelPosition: "ABOVE",
            required: if(
              or(
                a!isNullOrEmpty(
                  ri!nomination.isOpsAdditionalVettingReq
                ),
                ri!nomination.isOpsAdditionalVettingReq = true()
              ),
              true,
              false
            ),
            /*if(*/
            /*a!isUserMemberOfGroup(*/
            /*username: loggedInUser(),*/
            /*groups: {cons!CAW_GRP_REVIEWERS_COMMENTS_GROUP[4],cons!CAW_GRP_REVIEWERS_COMMENTS_GROUP[5],cons!CAW_GRP_REVIEWERS_COMMENTS_GROUP[6]}*/
            /*),*/
            /*false,*/
            /*true*/
            /*),*/
            showWhen: if(
              and(
                toboolean(local!isNewVersion) = true,
                #"urn:appian:function:v1:a:isusermemberofgroup?okey=a!isUserMemberOfGroup"(
                  username: loggedInUser(),
                  groups: {
                    #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12345157"[1],
                    #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12345157"[2],
                    #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12345157"[3],
                    #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12345157"[5],
                    #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12345157"[7],
                    #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12345157"[8]
                  }
                )
              ),
              true,
              false
            ),
            readOnly: or(a!isNotNullOrEmpty(ri!nomination.vettingReviewersComment),ri!readOnly),
            characterLimit: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3238137",
            value:local!reviewersComment,
            saveInto: {local!reviewersComment,
            a!save(ri!reviewercomment,local!reviewersComment)},
            refreshAfter: "UNFOCUS",
            height: "MEDIUM",
            disabled: if(
              #"urn:appian:function:v1:a:isusermemberofgroup?okey=a!isUserMemberOfGroup"(
                username: loggedInUser(),
                groups: {
                  #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12345157"[4],
                  #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12345157"[5],
                  #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12345157"[6]
                }
              ),
              true,
              false
            )
          )
        }
      )
    },
    isCollapsible: true,
    divider: "ABOVE",
    dividerWeight: "THIN",
    marginBelow: "STANDARD"
  )
)
